selector_to_html = {"a[href=\"#fine-tuning-tutorial\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Fine tuning tutorial<a class=\"headerlink\" href=\"#fine-tuning-tutorial\" title=\"Link to this heading\">\u00b6</a></h1><h2>Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">\u00b6</a></h2><p><strong>Adapting large language models</strong></p><p>Large language models (LLMs) are now ubiquitous in many applications and a\nvariety of both open- and closed-weight are available for many disparate tasks.\nHowever, it can be the case that an off-the-shelf model does not perform well\nin a specific task, or that we would like a smaller model focused on some\nspecific use cases and avoid expensive, large general-purpose models. In these\ncases, we need to find a way to \u201ctweak\u201d the behaviour of a model to fit the\nrequirements.\nA LLM can be adapted to a task in several ways: we can change the\ninstructions given to the model, provide external information at inference\ntime, or continue training the model on examples of the desired behaviour.</p>", "a[href=\"#software-and-infrastructure\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Software and infrastructure<a class=\"headerlink\" href=\"#software-and-infrastructure\" title=\"Link to this heading\">\u00b6</a></h2><p>The conceptual parts of the lesson do not require a GPU. Exercises can be\ncompleted through discussion or using an existing model interface.</p><p>A later hands-on fine-tuning lesson may use the Hugging Face ecosystem,\nincluding Transformers, Datasets, TRL, PEFT, and Accelerate. Those\nimplementation details are deliberately kept separate from the conceptual\nmaterial in this lesson.</p>", "a[href=\"#who-is-the-lesson-for\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Who is the lesson for?<a class=\"headerlink\" href=\"#who-is-the-lesson-for\" title=\"Link to this heading\">\u00b6</a></h2><p>The lesson is intended for researchers, research software engineers, and\ntechnical staff who want to understand how large language models can be\nadapted to specialist tasks.</p><p>The main focus is not on any particular model or software library (our example\nwill be, though). Instead, the lesson develops a conceptual framework that can\nbe applied when planning an LLM-based application or a fine-tuning experiment.</p>", "a[href=\"#see-also\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">See also<a class=\"headerlink\" href=\"#see-also\" title=\"Link to this heading\">\u00b6</a></h2><p>These lessons were inspired / adapted from the excellent material developed by the Vienna scientific cluster (VSC) <a class=\"reference external\" href=\"https://gitlab.tuwien.ac.at/vsc-public/training/LLMs-on-supercomputers\">here</a> [License: CC BY-SA 4.0]. Moreover, the Hugging Face people published a guidebook of sorts based on their experience training SmolLM, which can be found <a class=\"reference external\" href=\"https://huggingface.co/spaces/HuggingFaceTB/smol-training-playbook#beyond-base-modelspost-training-in-2025\">here</a>.</p>", "a[href=\"#id1\"]": "<figure class=\"align-default\" id=\"id1\">\n<a class=\"reference internal image-reference\" href=\"_images/adaptation-ladder.png\"><img alt=\"_images/adaptation-ladder.png\" src=\"_images/adaptation-ladder.png\" style=\"width: 95%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\">Prompt engineering changes the instructions. RAG adds external evidence.\nFine-tuning changes model parameters. Original figure created by VSC <a class=\"reference external\" href=\"https://gitlab.tuwien.ac.at/vsc-public/training/LLMs-on-supercomputers/-/tree/main/presentations?ref_type=heads\">here</a>.</span><a class=\"headerlink\" href=\"#id1\" title=\"Link to this image\">\u00b6</a></p>\n</figcaption>\n</figure>", "a[href=\"#lesson-schedule\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Lesson schedule<a class=\"headerlink\" href=\"#lesson-schedule\" title=\"Link to this heading\">\u00b6</a></h2><p>A possible schedule for a three-hour lesson is:</p>", "a[href=\"#learning-objectives\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Learning objectives<a class=\"headerlink\" href=\"#learning-objectives\" title=\"Link to this heading\">\u00b6</a></h2><p>By the end of the lesson, learners should be able to:</p>", "a[href=\"#overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">\u00b6</a></h2><p><strong>Adapting large language models</strong></p><p>Large language models (LLMs) are now ubiquitous in many applications and a\nvariety of both open- and closed-weight are available for many disparate tasks.\nHowever, it can be the case that an off-the-shelf model does not perform well\nin a specific task, or that we would like a smaller model focused on some\nspecific use cases and avoid expensive, large general-purpose models. In these\ncases, we need to find a way to \u201ctweak\u201d the behaviour of a model to fit the\nrequirements.\nA LLM can be adapted to a task in several ways: we can change the\ninstructions given to the model, provide external information at inference\ntime, or continue training the model on examples of the desired behaviour.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
